const buildDefaultAnswer = (question, variant = 0) => {
  const text = String(question || '').toLowerCase();
  if (/weinfuse|clinic|healthcare|insurance|billing|inventory|patient|treatment/.test(text)) return variant === 0
    ? 'I started with the real workflow and the people using it, then clarified the business rules with the domain expert. At WeInfuse, that approach helped me build dependable healthcare and insurance capabilities while refining them from stakeholder feedback.'
    : 'My healthcare work taught me to pair practical delivery with correctness and user trust. I would explain the workflow, validate edge cases, ship the smallest reliable improvement, and use frontline feedback to guide the next iteration.';
  if (/north star|ai|agent|llm|model|mcp|token|voice|simulator|automation/.test(text)) return variant === 0
    ? 'I ground AI behind a concrete workflow, bounded tools, structured outputs, and reviewable decisions. In North Star, I used deterministic filtering and focused context before model evaluation so the system stayed useful, explainable, and cost-aware.'
    : 'My strongest AI work is practical systems building: connect models to tools, memory, retrieval, and workflow state without surrendering control. I measure success by whether the user can complete a real task more reliably, not by whether the demo looks impressive.';
  if (/production|debug|bug|failure|reliab|legacy|migration|angular|react|rails|\.net|stack/.test(text)) return variant === 0
    ? 'I trace the user-visible problem across the full execution path, including frontend behavior, APIs, background jobs, and data flow. Then I make a durable fix, verify the important edge cases, and coordinate the resolution with the people affected.'
    : 'I prefer a small, observable change over a speculative rewrite. I map the current behavior, isolate the boundary where it breaks, preserve working behavior, and improve the surrounding design only when the evidence supports it.';
  if (/lead|mentor|team|stakeholder|collaborat|founder|ambig|forward|implementation|user/.test(text)) return variant === 0
    ? 'I work best by making the ambiguous workflow concrete with users and domain experts. I communicate tradeoffs plainly, take ownership through production, and keep stakeholders involved as evidence changes the implementation.'
    : 'I bring a blend of technical ownership and user empathy. I can move from discovery to architecture, implementation, debugging, and feedback while helping a new team make decisions without overcomplicating the first release.';
  return variant === 0
    ? 'I would answer with a specific example from my healthcare software or North Star work, explain the decision I owned, and connect the result to the role. I would keep the story concise and close with what I learned.'
    : 'My through-line is turning ambiguous, workflow-heavy problems into reliable software. I would give the interviewer the context, my action, the outcome, and one clear lesson that applies to this role.';
};
